}

items.solution:
function buildCacheKey({ method, url, varyOn = [], headers = {} }) {
  const varyPart = varyOn
    .map((h) => `${h}=${headers[h.toLowerCase()] ?? ""}`)
    .sort()
    .join("&");
  return `${method}:${url}${varyPart ? `?${varyPart}` : ""}`;
}

