items.solution:
function parseCacheControl(header) {
  const isPublic = header.includes("public");
  const match = header.match(/max-age=(\d+)/);
  const maxAgeMs = match ? Number(match[1]) * 1000 : 0;
  return { isPublic, maxAgeMs };
}

