items.solution:
function getCacheStatus(now, storedAt, maxAgeMs, staleWhileRevalidateMs) {
  const age = now - storedAt;
  if (age < maxAgeMs) return "FRESH";
  if (age < maxAgeMs + staleWhileRevalidateMs) return "STALE_WHILE_REVALIDATE";
  return "EXPIRED";
}

